import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Port 8000 la backend run aaganum
    axios.get('http://localhost:8000/api/analyze?tickers=RELIANCE.NS,TCS.NS')
      .then(res => {
        setData(res.data);
      })
      .catch(err => {
        console.error("Backend connection error:", err);
        setError("Backend run aagala! Terminal-la 'python main.py' check pannunga.");
      });
  }, []);

  if (error) return <div style={{color: 'red', textAlign: 'center', marginTop: '50px'}}>{error}</div>;
  if (!data) return <h2 style={{color: 'white', textAlign: 'center', marginTop: '50px'}}>🛡️ Analyzing Market Risk (Flowchart Logic)...</h2>;

  return (
    <div style={{ backgroundColor: '#0f172a', color: '#f8fafc', minHeight: '100vh', padding: '40px' }}>
      <h1>🛡️ QuantShield AI Optimizer (React)</h1>
      
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginTop: '30px' }}>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '12px' }}>
          <p>AI DECISION</p>
          <h2 style={{ color: data.decision === 'BUY' ? '#4ade80' : '#fbbf24' }}>{data.decision}</h2>
        </div>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '12px' }}>
          <p>BSI SCORE</p>
          <h2 style={{ color: '#3b82f6' }}>{data.bsi_score}</h2>
        </div>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '12px' }}>
          <p>REGIME</p>
          <h2>{data.regime}</h2>
        </div>
      </div>

      <h3 style={{ marginTop: '40px' }}>Investment Forecast (₹10,000 Scenario)</h3>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        <div style={{ background: 'linear-gradient(135deg, #064e3b, #065f46)', padding: '25px', borderRadius: '15px' }}>
          <p>💰 Expected Return</p>
          <h1>₹{data.forecast?.expected}</h1>
        </div>
        <div style={{ background: 'linear-gradient(135deg, #7f1d1d, #991b1b)', padding: '25px', borderRadius: '15px' }}>
          <p>⚠️ Worst Case</p>
          <h1>₹{data.forecast?.worst_case}</h1>
        </div>
      </div>
    </div>
  );
}

export default App;
